<script lang="ts">import type {WorkPackagePhaseProgress} from '../lib/model/entityTypes.ts';export let progress:WorkPackagePhaseProgress|null=null;</script>
{#if progress}<section class="phase-progress" data-testid="phase-progress"><div class="section-label"><span>Phase Progress</span><small>{progress.phases.filter(phase=>phase.status==='COMPLETE').length} / {progress.totalPhases} Complete · Phase {progress.currentPhaseNumber??'—'} Active</small></div><div class="phase-progress-list">{#each progress.phases as phase}<div class:active={phase.status==='ACTIVE'} class:complete={phase.status==='COMPLETE'} class="phase-progress-item"><span class="phase-marker" aria-hidden="true">{phase.status==='COMPLETE'?'✓':phase.status==='ACTIVE'?'●':'○'}</span><div><strong>Phase {phase.number} / {progress.totalPhases}</strong><span>{phase.title}</span><small>{phase.status}</small></div></div>{/each}</div></section>{:else}<section class="phase-progress phase-progress-empty" data-testid="phase-progress-empty"><div class="section-label"><span>Phase Progress</span></div><p>No phase plan</p></section>{/if}
